def _check(name, args, expected, run):
    stats["calls"] += 1
    try:
        actual = {"ok": enc(run())}
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as e:  # noqa: BLE001
        actual = {"error": error_text(e)}
    want = {"ok": enc(expected)}
    if canon(want, False) != canon(actual, False):
        stats["mismatches"] += 1
        _report({"fn": name, "args": args, "expected": want, "actual": actual})


